from fractions import Fraction
from typing import Dict, Tuple

Vec2 = Tuple[Fraction, Fraction]
Tensor = Dict[Tuple[int, int], Fraction]

def tensor(x: Vec2, y: Vec2) -> Tensor:
    """Elementary tensor x (x) y as a 2x2 coefficient table."""
    return {(a, b): x[a] * y[b] for a in (0, 1) for b in (0, 1)}

def add(t: Tensor, s: Tensor) -> Tensor:
    return {k: t.get(k, Fraction(0)) + s.get(k, Fraction(0)) for k in set(t) | set(s)}

if __name__ == "__main__":
    e1: Vec2 = (Fraction(1), Fraction(0))
    e2: Vec2 = (Fraction(0), Fraction(1))
    s:  Vec2 = (Fraction(1), Fraction(1))          # e1 + e2
    linear = add(tensor(e1, e1), tensor(e2, e2))    # forced by linearity
    clone  = tensor(s, s)                           # required by cloning
    cross = {k: clone[k] - linear.get(k, Fraction(0)) for k in clone}
    print("cross terms (must be zero for a cloner):", dict(sorted(cross.items())))
    print("nonzero => no linear cloner exists")

