from typing import Callable, List, Sequence

def decide_person_equivalence(f: Callable[[int], object], g: Callable[[int], object],
                              stimuli: Sequence[int]) -> bool:
    """Decide f ~ g over a finite stimulus space in |stimuli| comparisons."""
    for i in stimuli:
        if f(i) != g(i):
            return False   # i is a distinguishing stimulus
    return True

from fractions import Fraction
from typing import Dict, Tuple

def cloner_cross_defect() -> Dict[Tuple[int, int], Fraction]:
    """Compute the cross-term defect obstructing a linear cloner on k^2.
    Returns nonzero coefficients => no linear map C with C(x)=x(x)x exists."""
    def tens(x, y): return {(a, b): x[a] * y[b] for a in (0, 1) for b in (0, 1)}
    e1 = (Fraction(1), Fraction(0)); e2 = (Fraction(0), Fraction(1))
    s = (Fraction(1), Fraction(1))
    lin = {k: tens(e1, e1).get(k, Fraction(0)) + tens(e2, e2).get(k, Fraction(0))
           for k in set(tens(e1, e1)) | set(tens(e2, e2))}
    clo = tens(s, s)
    return {k: clo[k] - lin.get(k, Fraction(0)) for k in clo if clo[k] != lin.get(k, Fraction(0))}
